SELECT game_id, status_key, name, description, status_kind, status, sort_order, created_at, updated_at
FROM public.statuses
WHERE game_id = #{gameId}

    AND (
        strpos(lower(status_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND status = #{status}

ORDER BY sort_order ASC, name ASC, status_key ASC

SELECT game_id, status_key, name, description, status_kind, status, sort_order, created_at, updated_at
FROM public.statuses
WHERE game_id = #{gameId} AND status_key = #{statusKey}

SELECT COUNT(1)
FROM public.statuses
WHERE game_id = #{gameId} AND status_key = #{statusKey}

